import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  Scale, FileText, Search, Shield, UploadCloud, Download, Edit3,
  CheckCircle2, ChevronRight, LogOut, Bold, Italic, AlignLeft,
  AlignCenter, File, BookOpen, Gavel, ArrowRight, FileCheck2,
  MessageSquare, Loader2, AlertCircle, X, Menu, ChevronDown,
  Sparkles, Landmark, ScrollText, Users, Star, Send, RotateCcw,
  Copy, Check, PenLine, Brain, Zap, Database
} from 'lucide-react';

// ─── API layer ────────────────────────────────────────────────────────────────
const API_BASE = process.env.REACT_APP_API_URL || '';

const api = {
  async draft(chatHistory) {
    // chatHistory: [{ role: "user", text: "..." }, { role: "agent", text: "..." }]
    const res = await fetch(`${API_BASE}/draft`, { 
      method: 'POST', 
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        messages: chatHistory, 
        user_id: 'web_user' 
      }) 
    });
    return res.json();
  },
  async rag(query) {
    const form = new FormData();
    form.append('query', query);
    const res = await fetch(`${API_BASE}/rag`, { method: 'POST', body: form });
    return res.json();
  },
  async summarize(file) {
    const form = new FormData();
    form.append('file', file);
    const res = await fetch(`${API_BASE}/summarize`, { method: 'POST', body: form });
    return res.json();
  },
  async health() {
    try {
      const res = await fetch(`${API_BASE}/health`);
      return res.ok;
    } catch { return false; }
  }
};

// ─── Helper: download as properly formatted .docx (RTF Word-compatible) ─────
function downloadDocx(text, filename = 'petition.docx') {
  // Build RTF — universally opened by MS Word, LibreOffice, Google Docs
  const escapeRtf = (s) => s
    .replace(/\\/g, '\\\\')
    .replace(/[{}]/g, (c) => '\\' + c)
    .replace(/[\u0080-\uFFFF]/g, (c) => `\\u${c.charCodeAt(0)}?`);

  const lines = text.split('\n');
  let rtfBody = '';
  for (const line of lines) {
    const trimmed = line.trim();
    const esc = escapeRtf(trimmed);

    // Court header (ALL CAPS lines at top, or lines with "IN THE")
    if (/^IN THE (HIGH|SUPREME|COURT|SESSIONS)/i.test(trimmed) ||
        /^(HABEAS CORPUS|CONSTITUTIONAL PETITION|APPLICATION FOR)/i.test(trimmed)) {
      rtfBody += `\\pard\\qc\\sb240\\sa60\\b\\fs26 ${esc}\\b0\\par\n`;
    }
    // Section headings: FACTS, GROUNDS, PRAYER, VERIFICATION, INTERIM
    else if (/^(FACTS|GROUNDS|PRAYER|VERIFICATION|INTERIM|MOST RESPECTFULLY)/i.test(trimmed)) {
      rtfBody += `\\pard\\ql\\sb240\\sa60\\b\\fs24 ${esc}\\b0\\par\n`;
    }
    // Lettered grounds A. B. C.
    else if (/^[A-Z]\.\s/.test(trimmed)) {
      rtfBody += `\\pard\\ql\\li360\\fi-360\\sb120\\sa60\\fs22 ${esc}\\par\n`;
    }
    // Numbered prayers i. ii. iii.
    else if (/^(i{1,3}v?|vi{0,3}|ix|x)\.\s/i.test(trimmed)) {
      rtfBody += `\\pard\\ql\\li360\\fi-360\\sb80\\sa40\\fs22 ${esc}\\par\n`;
    }
    // That... (fact paragraphs)
    else if (/^That\b/.test(trimmed)) {
      rtfBody += `\\pard\\qj\\sb120\\sa60\\fs22 ${esc}\\par\n`;
    }
    // Versus / party lines
    else if (/^\.+\.\.\.(Petitioner|Respondent|Applicant)$/.test(trimmed) || trimmed === 'Versus') {
      rtfBody += `\\pard\\qc\\sb60\\sa60\\fs22 ${esc}\\par\n`;
    }
    // Empty line
    else if (!trimmed) {
      rtfBody += `\\pard\\sb60\\sa60\\fs22 \\par\n`;
    }
    // Default body text
    else {
      rtfBody += `\\pard\\qj\\sb80\\sa40\\fs22 ${esc}\\par\n`;
    }
  }

  const rtf = `{\\rtf1\\ansi\\deff0
{\\fonttbl{\\f0\\froman\\fcharset0 Times New Roman;}}
{\\colortbl ;\\red0\\green0\\blue0;}
\\paperw12240\\paperh15840
\\margl1800\\margr1800\\margt1440\\margb1440
\\f0\\cf1
${rtfBody}
}`;

  const blob = new Blob([rtf], { type: 'application/rtf' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename.replace('.docx', '.rtf'); // .rtf opens in Word perfectly
  a.click();
  URL.revokeObjectURL(url);
}

// ─── Helper: open print window with petition only, properly formatted ─────
function printPetition(text, docName = 'petition') {
  const escHtml = (s) => s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  const lines = text.split('\n');
  let htmlBody = '';

  for (const line of lines) {
    const trimmed = line.trim();
    const esc = escHtml(trimmed);

    if (!trimmed) {
      htmlBody += '<div class="spacer"></div>';
    } else if (/^IN THE (HIGH|SUPREME|COURT|SESSIONS)/i.test(trimmed) ||
               /^(HABEAS CORPUS|CONSTITUTIONAL PETITION|APPLICATION FOR)/i.test(trimmed) ||
               /^Writ Petition|^Crl\. Misc/i.test(trimmed)) {
      htmlBody += `<p class="court-header">${esc}</p>`;
    } else if (/^(FACTS|GROUNDS|PRAYER|VERIFICATION|INTERIM\/URGENT PRAYER|MOST RESPECTFULLY)/i.test(trimmed)) {
      htmlBody += `<p class="section-heading">${esc}</p>`;
    } else if (/^Versus$/i.test(trimmed)) {
      htmlBody += `<p class="versus">${esc}</p>`;
    } else if (/\.+\.(Petitioner|Respondent|Applicant|Deponent)$/.test(trimmed)) {
      htmlBody += `<p class="party-line">${esc}</p>`;
    } else if (/^[A-Z]\.\s/.test(trimmed)) {
      htmlBody += `<p class="ground">${esc}</p>`;
    } else if (/^(i{1,3}v?|vi{0,3}|ix|x)\./i.test(trimmed)) {
      htmlBody += `<p class="prayer-item">${esc}</p>`;
    } else if (/^That\b/.test(trimmed)) {
      htmlBody += `<p class="fact-para">${esc}</p>`;
    } else if (/^(Through Counsel|Advocate,|Enrollment|Cell:|Sworn at)/i.test(trimmed)) {
      htmlBody += `<p class="counsel-line">${esc}</p>`;
    } else if (/^_{10,}$/.test(trimmed)) {
      htmlBody += `<p class="sig-line">${esc}</p>`;
    } else {
      htmlBody += `<p class="body-text">${esc}</p>`;
    }
  }

  const printHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>${escHtml(docName)}</title>
  <style>
    @page {
      size: A4;
      margin: 2.5cm 2.8cm 2.5cm 2.8cm;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: "Times New Roman", Times, serif;
      font-size: 12pt;
      line-height: 1.8;
      color: #000;
      background: #fff;
    }
    .court-header {
      text-align: center;
      font-weight: bold;
      font-size: 12pt;
      margin: 8pt 0 4pt;
      text-transform: uppercase;
      letter-spacing: 0.5pt;
    }
    .section-heading {
      font-weight: bold;
      font-size: 12pt;
      margin: 18pt 0 8pt;
      text-decoration: underline;
      text-transform: uppercase;
      letter-spacing: 0.5pt;
    }
    .versus {
      text-align: center;
      font-weight: bold;
      margin: 6pt 0;
    }
    .party-line {
      text-align: justify;
      margin: 3pt 0;
    }
    .ground {
      text-align: justify;
      margin: 8pt 0 4pt 24pt;
      text-indent: -24pt;
    }
    .prayer-item {
      text-align: justify;
      margin: 6pt 0 4pt 36pt;
      text-indent: -24pt;
    }
    .fact-para {
      text-align: justify;
      margin: 6pt 0;
      text-indent: 24pt;
    }
    .body-text {
      text-align: justify;
      margin: 4pt 0;
    }
    .counsel-line {
      margin: 4pt 0;
    }
    .sig-line {
      margin: 12pt 0 4pt;
      letter-spacing: 2pt;
    }
    .spacer {
      height: 8pt;
    }
    .separator {
      border: none;
      border-top: 1px solid #000;
      margin: 12pt 0;
    }
    @media print {
      body { -webkit-print-color-adjust: exact; }
    }
  </style>
</head>
<body>
${htmlBody}
<script>
  window.onload = function() {
    window.print();
    window.onafterprint = function() { window.close(); };
  };
</script>
</body>
</html>`;

  const win = window.open('', '_blank', 'width=900,height=700');
  win.document.write(printHtml);
  win.document.close();
}

function downloadTxt(text, filename = 'petition.txt') {
  const blob = new Blob([text], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

// ─── Reusable Components ──────────────────────────────────────────────────────
const GoldDivider = () => (
  <div className="flex items-center gap-3 my-2">
    <div className="flex-1 h-px bg-gradient-to-r from-transparent via-yellow-600/40 to-transparent" />
    <Scale className="w-3 h-3 text-yellow-600/60" />
    <div className="flex-1 h-px bg-gradient-to-r from-transparent via-yellow-600/40 to-transparent" />
  </div>
);

const StatusDot = ({ online }) => (
  <span className="flex items-center gap-1.5">
    <span className={`relative flex h-2 w-2`}>
      {online && <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75" />}
      <span className={`relative inline-flex rounded-full h-2 w-2 ${online ? 'bg-emerald-500' : 'bg-red-500'}`} />
    </span>
    <span className="text-[10px] text-slate-400 uppercase tracking-widest">{online ? 'Online' : 'Offline'}</span>
  </span>
);

// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [page, setPage] = useState('landing');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState('drafter');
  const [apiOnline, setApiOnline] = useState(null);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    api.health().then(setApiOnline);
    const interval = setInterval(() => api.health().then(setApiOnline), 30000);
    return () => clearInterval(interval);
  }, []);

  const navigate = useCallback((p) => {
    setPage(p);
    setMobileMenuOpen(false);
    window.scrollTo(0, 0);
  }, []);

  const login = () => { setIsLoggedIn(true); navigate('workspace'); };
  const logout = () => { setIsLoggedIn(false); navigate('landing'); };

  // ── Navbar ──────────────────────────────────────────────────────────────────
  const Navbar = () => (
    <nav className="bg-navy-900/95 backdrop-blur border-b border-white/5 sticky top-0 z-50" style={{background:'rgba(10,22,40,0.97)'}}>
